; -------------------------------------------------------------------------
; SH-2 program metadata
; -------------------------------------------------------------------------

	align	$10
	dc.b	'MARS CHECK MODE '
	dc.l	0
	dc.l	Sh2Program-MARS_ROM_FIXED
	dc.l	0
	dc.l	$9000
