; -------------------------------------------------------------------------
; Hard reset
; -------------------------------------------------------------------------
	
HardReset:
	incbin	"mars/mars_init.bin"

; -------------------------------------------------------------------------

	bcc.s	.Success
	btst	#5,d0
	beq.s	.NoMars

.ChecksumFail:
	moveq	#$11,d0
	bra.w	DisplayError
	
.NoMars:
	cmpi.l	#'MARS',MARS_ID
	beq.w	UnkMarsError
	bra.s	NoMars

.Success:
	clr.l	init_flag
	
	tst.w	d0
	bpl.w	InitGame
	
	btst	#0,MARS_ADAPTER
	bne.s	SoftReset
	move.l	#0,MARS_COMM_8
	
	lea	StartMarsReinit(pc),a0
	lea	RAM_START,a1
	movea.l	a1,a2
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	jmp	(a2)

; -------------------------------------------------------------------------
; Function to reinitialize the 32X
; -------------------------------------------------------------------------

StartMarsReinit:
	obj	RAM_START
	move.b	#1,MARS_ADAPTER
	jmp	ReinitMars
	objend

; -------------------------------------------------------------------------
; Soft reset
; -------------------------------------------------------------------------

SoftReset:
	btst	#1,MARS_ADAPTER
	bne.w	InitGame

ReinitMars:
	lea	IO_BASE,a5
	movea.l	#$FFFFFFC0,a4
	move.w	#$F3C,d7
	jmp	HardReset+$2F4

; -------------------------------------------------------------------------
; No 32X detected
; -------------------------------------------------------------------------

NoMars:
	btst	#1,VDP_CTRL+1
	bne.s	NoMars
	tst.l	IO_CTRL_1-1
	bne.s	loc_88089A
	tst.w	IO_CTRL_3-1

loc_88089A:
	bne.s	loc_880918
	lea	word_88091A(pc),a5
	movem.w	(a5)+,d5-d7
	movem.l	(a5)+,a0-a4
	move.b	-$10FF(a1),d0
	andi.b	#$F,d0
	beq.s	loc_8808BA
	move.l	#"SEGA",$2F00(a1)

loc_8808BA:
	move.w	(a4),d0
	moveq	#0,d0
	movea.l	d0,a6
	move.l	a6,usp
	moveq	#$17,d1

