	move.w	d7,(a2)

loc_8808E8:
	move.l	d0,-(a6)
	dbf	d6,loc_8808E8
	move.l	(a5)+,(a4)
	move.l	(a5)+,(a4)
	moveq	#$1F,d3

loc_8808F4:
	move.l	d0,(a3)
