; -------------------------------------------------------------------------
; Initialize the game
; -------------------------------------------------------------------------

InitGame:
.WaitMaster
	cmpi.l	#'M_OK',MARS_COMM_0
	bne.s	.WaitMaster

.WaitSlave:
	cmpi.l	#'S_OK',MARS_COMM_4
	bne.s	.WaitSlave
	
	move.l	#'INIT',init_flag
	cmpi.l	#'INIT',init_flag
	bne.s	InitGame
	
	movea.l	MARS_ROM_FIXED,sp
	lea	MAPPER_CTRL,a1
	tst.b	(a1)
	moveq	#0,d0
	jsr	BankSet
	
	move.l	MARS_ROM_FIXED+$70,d0
	move.l	d0,MARS_HEADER+$70
	
	move.b	#2,MARS_BANK
	bsr.w	GetVersion
	bsr.w	CheckRegion
	
	moveq	#0,d0
	move.l	d0,MARS_COMM_0
	move.l	d0,MARS_COMM_4
	move.l	d0,MARS_COMM_8
	move.l	d0,MARS_COMM_12
	
	jsr	sub_881868
	
	lea	dword_FFFFC0,a0
	cmpi.l	#"SEGA",(a0)
	bne.s	.ClearRetainedVars
	
	move.b	IO_CTRL_1,d0
	and.b	IO_CTRL_2,d0
	and.b	IO_CTRL_3,d0
	btst	#6,d0
	bne.s	.ClearRegs

.ClearRetainedVars:
	moveq	#0,d1
	move.l	d1,(a0)
	lea	8(a0),a1
	moveq	#$D,d0

.ClearRetainedLoop:
	move.l	d1,(a1)+
	dbf	d0,.ClearRetainedLoop
	
	move.l	#"SEGA",(a0)

.ClearRegs:
	moveq	#0,d0
	moveq	#0,d1
	moveq	#0,d2
	moveq	#0,d3
	moveq	#0,d4
	moveq	#0,d5
	moveq	#0,d6
	movea.w	d0,a2
	move.w	#$7FD,d7

.ClearRAM:
	movem.l	d0-d6/a2,-(a0)
	dbf	d7,.ClearRAM
	
	lea	byte_FFC000,a0
	move.w	#$4EF9,d0
	lea	nullsub_3(pc),a1
	moveq	#2,d7

.SetIntJumps:
	move.w	d0,(a0)+
	move.l	a1,(a0)+
	dbf	d7,.SetIntJumps
	lea	NullInterrupt(pc),a1
	moveq	#6,d7

.SetupIntJumps:
	move.w	d0,(a0)+
	move.l	a1,(a0)+
	dbf	d7,.SetupIntJumps
	moveq	#$40,d0
	move.b	d0,IO_CTRL_1
	move.b	d0,IO_CTRL_2
	move.b	d0,IO_CTRL_3

.WaitDMA:
	move.w	VDP_CTRL,d0
	btst	#1,d0
	bne.s	.WaitDMA
	
	lea	VDP_DATA,a0
	move.w	#$8F02,VDP_CTRL
	move.w	#$8F02,vdp_reg_8F
	
	moveq	#0,d0
	move.l	#$40000000,4(a0)
	move.w	#$FFF,d1
	bsr.w	FillVDP
	
	move.l	#$C0000000,4(a0)
	moveq	#7,d1
	bsr.w	FillVDP
	
	move.l	#$40000010,4(a0)
	moveq	#4,d1
	bsr.w	FillVDP
	
	lea	InitialVDPRegs(pc),a0
	jsr	SetupVDPRegs
	
	move.w	#$100,Z80_RESET
	
	bsr.w	GetVersion
	move	#$2000,sr

.Loop:
	jsr	GameLoop
	bra.s	.Loop


; =============== S U B R O U T I N E =======================================


FillVDP:
	move.l	d0,(a0)
	move.l	d0,(a0)
	move.l	d0,(a0)
	move.l	d0,(a0)
	dbf	d1,FillVDP
	rts


