; -------------------------------------------------------------------------
; Load stage art
; -------------------------------------------------------------------------

LoadStageArt:
	lea	StageArtIndex,a6				; Get stage art list
	bsr.w	GetStageDataIndex
	
	moveq	#0,d7						; Initial tile offset
	move.w	d7,stage_art_fg					; Set foreground tile offset

.GetArtLoop:
	move.l	(a6)+,d0					; Get pointer
	bne.s	.GetArtData					; If it is a pointer, branch
	move.w	d7,stage_art_bg					; Set background tile offset
	bra.s	.GetArtLoop

.GetArtData:
	cmpi.l	#$FFFFFFFF,d0					; Are we at the end of the list?
	beq.s	.End						; If so, branch

	movea.l	d0,a0						; Get length of decompressed art
	move.w	(a0),d0
	andi.w	#$7FFF,d0

	movem.w	d0/d7,-(sp)					; Convert tile offset to VRAM write command
	lsl.w	#5,d7
	lsl.l	#2,d7
	lsr.w	#2,d7
	ori.w	#$4000,d7
	swap	d7
	andi.w	#3,d7

	move	#$2700,sr					; Decompress art into VRAM
	move.l	d7,VDP_CTRL
	jsr	NemDec
	move	#$2300,sr
	movem.w	(sp)+,d0/d7

	add.w	d0,d7						; Advance tile offset
	bra.s	.GetArtLoop					; Get next set of art

.End:
	rts


