	lea	plc_buffer,a1
	moveq	#$F,d0

.Clear:
	clr.l	(a1)+
	clr.w	(a1)+
	dbf	d0,.Clear
	rts


; =============== S U B R O U T I N E =======================================


ProcessPLC:
	tst.l	plc_buffer
	beq.s	.End
	tst.w	plc_tile_count
	bne.s	.End
	movea.l	plc_buffer,a0
	lea	NemPCD_WriteRowToVDP(pc),a3
	lea	nem_buffer,a1
	move.w	(a0)+,d2
	bpl.s	.NotXOR
	adda.w	#$A,a3

.NotXOR:
	andi.w	#$7FFF,d2
	move.w	d2,plc_tile_count
	bsr.w	NemDec_BuildCodeTable
	move.b	(a0)+,d5
	asl.w	#8,d5
	move.b	(a0)+,d5
	moveq	#$10,d6
	moveq	#0,d0
	move.l	a0,plc_buffer
	move.l	a3,plc_nem_write
	move.l	d0,plc_repeat
	move.l	d0,plc_pixel
	move.l	d0,plc_row
	move.l	d5,plc_read
	move.l	d6,plc_shift

.End:
	rts


